-- Run in a dedicated MIPTV Neon database. Never use a TAKCO/FAMMA database.
CREATE TABLE IF NOT EXISTS customers (id BIGSERIAL PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,email TEXT,phone TEXT,address TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS suppliers (id BIGSERIAL PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,email TEXT,phone TEXT,address TEXT,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS items (id BIGSERIAL PRIMARY KEY,sku TEXT UNIQUE NOT NULL,name TEXT NOT NULL,category TEXT,unit TEXT DEFAULT 'pcs',cost NUMERIC(14,3) DEFAULT 0,price NUMERIC(14,3) DEFAULT 0,quantity NUMERIC(14,3) DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS sales_orders (id BIGSERIAL PRIMARY KEY,number TEXT UNIQUE NOT NULL,customer_code TEXT REFERENCES customers(code),date DATE DEFAULT CURRENT_DATE,status TEXT DEFAULT 'draft',total NUMERIC(14,3) DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS sales_invoices (id BIGSERIAL PRIMARY KEY,number TEXT UNIQUE NOT NULL,customer_code TEXT REFERENCES customers(code),date DATE DEFAULT CURRENT_DATE,status TEXT DEFAULT 'draft',total NUMERIC(14,3) DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS purchase_orders (id BIGSERIAL PRIMARY KEY,number TEXT UNIQUE NOT NULL,supplier_code TEXT REFERENCES suppliers(code),date DATE DEFAULT CURRENT_DATE,status TEXT DEFAULT 'draft',total NUMERIC(14,3) DEFAULT 0,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS sales_order_lines (id BIGSERIAL PRIMARY KEY,order_id BIGINT REFERENCES sales_orders(id),sku TEXT REFERENCES items(sku),quantity NUMERIC(14,3) NOT NULL,unit_price NUMERIC(14,3) NOT NULL);
CREATE TABLE IF NOT EXISTS sales_invoice_lines (id BIGSERIAL PRIMARY KEY,invoice_id BIGINT REFERENCES sales_invoices(id),sku TEXT REFERENCES items(sku),quantity NUMERIC(14,3) NOT NULL,unit_price NUMERIC(14,3) NOT NULL);
CREATE TABLE IF NOT EXISTS stock_movements (id BIGSERIAL PRIMARY KEY,sku TEXT REFERENCES items(sku),movement_type TEXT NOT NULL,quantity NUMERIC(14,3) NOT NULL,reference TEXT,created_at TIMESTAMPTZ DEFAULT now());
